@extends('layout')@section('content')<h1>{{ $task->exists ? 'Edit Task' : 'Create Task' }}</h1><form method="POST" action="{{ $task->exists ? route('tasks.update',$task) : route('tasks.store') }}">@csrf @if($task->exists) @method('PATCH') @endif<label>Title<input name="title" maxlength="100" value="{{ old('title',$task->title) }}" required></label>@error('title')<p class="error">{{ $message }}</p>@enderror<label>Description<textarea name="description">{{ old('description',$task->description) }}</textarea></label>@error('description')<p class="error">{{ $message }}</p>@enderror<label>Status<select name="status">@foreach(['pending'=>'Pending','in_progress'=>'In progress','done'=>'Done'] as $value=>$label)<option value="{{ $value }}" @selected(old('status',$task->status ?? 'pending')===$value)>{{ $label }}</option>@endforeach</select></label>@error('status')<p class="error">{{ $message }}</p>@enderror<label>Due date<input type="date" name="due_date" value="{{ old('due_date',$task->due_date?->format('Y-m-d')) }}"></label>@error('due_date')<p class="error">{{ $message }}</p>@enderror<button>{{ $task->exists ? 'Update' : 'Save' }}</button></form>@endsection